{
  "$schema": "https://opencode.ai/config.json",
  "provider": {
    "nim": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "NVIDIA NIM FREE via nim-proxy",
      "options": {
        "baseURL": "http://127.0.0.1:8000/v1",
        "apiKey": "{env:NIM_PROXY_KEY}",
        "timeout": false
      },
      "models": {
        "z-ai/glm-5.3-flash": {
          "name": "GLM-5.3 Flash MAX",
          "limit": {
            "context": 131072,
            "output": 32768
          },
          "options": {
            "temperature": 0.6,
            "top_p": 0.95
          }
        },
        "nvidia/nemotron-3-super-120b-a12b": {
          "name": "Super 120B MAX",
          "limit": {
            "context": 131072,
            "output": 32768
          },
          "options": {
            "temperature": 0.6,
            "top_p": 0.95
          }
        }
      }
    }
  },
  "model": "nim/z-ai/glm-5.3-flash",
  "small_model": "nim/z-ai/glm-5.3-flash",
  "compaction": {
    "auto": true,
    "prune": true,
    "reserved": 24000
  },
  "instructions": [
    "Prefer ffs (/home/toxic/bin/ffs) over fd/rg/grep/glob/cat for all file finding, content search, and file reading: `ffs find`, `ffs grep`, `ffs read`, `ffs outline`, `ffs symbol`, `ffs refs`. The tau-ffs extension exposes ffs_find/ffs_grep/ffs_read/ffs_outline/ffs_symbol/ffs_refs/ffs_impact tools - use them instead of shelling out."
  ]
}

